mapper.update:
update trade_order
status = #{status}, pay_status = #{payStatus}, pay_time = #{payTime}, pay_no = #{payNo}, pickup_place = #{pickupPlace}, remark = #{remark}, expire_time = #{expireTime}, finish_time = #{finishTime}, cancel_reason = #{cancelReason}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select o.id, o.order_no, o.seller_id, o.buyer_id, o.product_id, o.real_price, o.deal_type, o.order_source, o.status, o.pay_status, o.pay_time, o.pickup_place, o.remark, o.expire_time, o.finish_time, o.cancel_reason, o.create_time, p.title as productTitle, p.images as productImages from trade_order o left join product p on o.product_id = p.id
and o.buyer_id = #{buyerId} and o.seller_id = #{sellerId} and o.status = #{status}
order by o.create_time desc
